// usePersonaUseBridge (#change-a-panes-persona-from-the-cli) — apply a `bsc persona use` request to the
// store and ACK it.
//
// THE ROUND TRIP
//   bsc persona use → request file → Rust watcher → `bsc://persona-use` → HERE → store → `persona_use_ack`
//
// The ack is load-bearing rather than ceremony: applying a persona RELAUNCHES the pane (see
// `applyPersonaUse`), so a change that silently failed would leave a killed session behind a caller that
// believes it came back under a new identity. So this ALWAYS acks — success or a stated error.
import { useEffect } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";
import { useAppStore } from "@/store";
import { safeInvoke } from "@/shared/lib/core/safeInvoke";
import { log } from "@/shared/lib/core/log";
import { applyPersonaUse, type PersonaUseRequest, type PersonaUseAck } from "@/app/personaUseBridge";

/**
 * Listen for `bsc://persona-use` and apply it. Mounted once by the shell.
 *
 * A thin adapter: the DECISION lives in `personaUseBridge.ts`, unit-testable without Tauri.
 */
export function usePersonaUseBridge(): void {
  useEffect(() => {
    let disposed = false;
    const un = listen<PersonaUseRequest & { id: string }>("bsc://persona-use", async (e) => {
      const { id, ...req } = e.payload;
      let ack: PersonaUseAck;
      try {
        // Read every action off a LIVE getState, not a captured snapshot: zustand hands out a new
        // object per update, so a stale closure could call into an older tab list.
        ack = await applyPersonaUse(id, req, {
          personaIds: () => (useAppStore.getState().personas ?? []).map((p) => p.id),
          currentPersona: (p) => useAppStore.getState().panePersonas?.[p],
          setPanePersona: (p, persona) => useAppStore.getState().setPanePersona(p, persona),
          killPane: async (p) => { await safeInvoke("pty_kill", { paneId: p }, undefined); },
          wakePane: (p, t) => useAppStore.getState().wakePane(p, t),
        });
      } catch (err) {
        // A throw here would strand the Rust waiter until its timeout. State it instead.
        ack = {
          id,
          error: `persona use threw: ${err instanceof Error ? err.message : String(err)}`,
          applied: false,
          relaunched: false,
        };
        log.error(`persona use ${id} threw: ${String(err)}`);
      }
      void invoke("persona_use_ack", { ack: { ...ack, id } }).catch((e2) => {
        // Nothing left to do — the caller will time out. Log it so the cause isn't a mystery.
        log.error(`persona_use_ack failed for ${id}: ${String(e2)}`);
      });
    });
    return () => {
      disposed = true;
      void un.then((f) => {
        if (disposed) f();
      });
    };
  }, []);
}
